'use strict';

// MODULES //

var tape = require( 'tape' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var factory = require( './../lib/factory.js' );


// FIXTURES //

var data = require( './fixtures/julia/data.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a function', function test( t ) {
	var mgf = factory( 2.0, 3.0 );
	t.strictEqual( typeof mgf, 'function', 'returns expected value' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the created function returns `NaN`', function test( t ) {
	var mgf;
	var y;

	mgf = factory( 2.0, 3.0 );
	y = mgf( NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( NaN, 3.0 );
	y = mgf( 0.1 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( 2.0, NaN );
	y = mgf( 0.1 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a nonpositive `mu`, the created function always returns `NaN`', function test( t ) {
	var mgf;
	var y;

	mgf = factory( 0.0, 3.0 );
	y = mgf( 0.1 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( -1.0, 3.0 );
	y = mgf( 0.1 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( NINF, 3.0 );
	y = mgf( 0.1 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( NINF, PINF );
	y = mgf( 0.1 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( NINF, NINF );
	y = mgf( 0.1 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( NINF, NaN );
	y = mgf( 0.1 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a nonpositive `lambda`, the created function always returns `NaN`', function test( t ) {
	var mgf;
	var y;

	mgf = factory( 2.0, 0.0 );
	y = mgf( 0.1 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( 2.0, -1.0 );
	y = mgf( 0.1 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( 2.0, NINF );
	y = mgf( 0.1 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( PINF, NINF );
	y = mgf( 0.1 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( NINF, NINF );
	y = mgf( 0.1 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( NaN, NINF );
	y = mgf( 0.1 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a value of x > lambda/(2*mu^2), the created function returns `NaN`', function test( t ) {
	var mgf;
	var y;

	mgf = factory( 1.0, 1.0 );
	y = mgf( 0.9 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = mgf( 5.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the created function evaluates the MGF for `x` given positive `mu` and `lambda`', function test( t ) {
	var expected;
	var lambda;
	var mgf;
	var mu;
	var x;
	var y;
	var i;

	expected = data.expected;
	x = data.x;
	mu = data.mu;
	lambda = data.lambda;
	for ( i = 0; i < x.length; i++ ) {
		mgf = factory( mu[ i ], lambda[ i ] );
		y = mgf( x[ i ] );
		if ( expected[ i ] !== null ) {
			t.ok( isAlmostSameValue( y, expected[ i ], 150 ), 'within tolerance. x: '+x[ i ]+'. mu: '+mu[ i ]+'. lambda: '+lambda[ i ]+'. y: '+y+'. E: '+expected[ i ]+'.' );
		}
	}
	t.end();
});
